import dataclasses
import hashlib
import hmac
import json
import threading
import unittest

from nearproof import (
    Consensus,
    CrlProof,
    CrlProofAuditor,
    CrlState,
    RangeDecision,
    _CRL_STATE_PREFIX,
    _crl_proof_mac,
    _crl_state_mac,
    _crl_state_payload,
    _encode_payload,
    _parse_crl_proof_hex,
    attest_observation_for_point,
    cert,
    make_crl,
    prove_crl,
)

ROOT = b"\x09" * 32
OTHER_ROOT = b"\x08" * 32
KEY_A = b"\xaa" * 32
KEY_B = b"\xbb" * 32
KEY_C = b"\xcc" * 32

KEYS = {"a": KEY_A, "b": KEY_B, "c": KEY_C}
POSITIONS = {"a": (3.0, 0.0), "b": (0.0, 4.0), "c": (0.0, 0.0)}

POINT = (0.0, 0.0)
CONTEXT = "room-7"


def decision(upper_bound=5.0, *, accepted=True, sample_count=1):
    return RangeDecision(
        sample_count=sample_count, upper_bound=upper_bound, accepted=accepted
    )


